-- ===========================================================================
-- Crazy Vinyl Shop — CMS schema
--
-- Run this once against a fresh Supabase project (SQL Editor → New query →
-- paste → Run), then run 0002_seed_content.sql.
--
-- Shape of the thing: the public website is static HTML generated by
-- tools/build.py. This database is the editing surface. Admins write `draft`,
-- publishing copies draft → published and snapshots the old published row into
-- content_versions, and a GitHub Actions rebuild reads the published rows and
-- regenerates the site. Anonymous visitors never touch these tables — they are
-- served plain HTML — so every policy below requires an admin.
-- ===========================================================================

-- ---------------------------------------------------------------- profiles

create table if not exists public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  email       text,
  role        text not null default 'viewer' check (role in ('viewer', 'admin')),
  created_at  timestamptz not null default now()
);

comment on table public.profiles is
  'One row per auth user. role defaults to viewer: signing up never grants write access.';

-- Every new auth user gets a viewer profile. SECURITY DEFINER so the insert
-- happens regardless of the policies below; the hard-coded default role is
-- what keeps a self-registered visitor out.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, email)
  values (new.id, new.email)
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- SECURITY DEFINER so policies can call it without re-entering RLS on
-- profiles, which would recurse.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
$$;

grant execute on function public.is_admin() to authenticated;

-- ----------------------------------------------------------- content docs

create table if not exists public.content_docs (
  key               text primary key,
  label             text not null,
  draft             jsonb not null default '{}'::jsonb,
  published         jsonb not null default '{}'::jsonb,
  draft_updated_at  timestamptz,
  draft_updated_by  uuid references auth.users (id) on delete set null,
  published_at      timestamptz,
  published_by      uuid references auth.users (id) on delete set null
);

comment on column public.content_docs.draft is
  'What the admin is editing. Invisible to the website until published.';
comment on column public.content_docs.published is
  'What the last build used. tools/build.py reads only this column.';

create table if not exists public.content_versions (
  id            bigint generated always as identity primary key,
  doc_key       text not null references public.content_docs (key) on delete cascade,
  snapshot      jsonb not null,
  note          text,
  published_at  timestamptz not null default now(),
  published_by  uuid references auth.users (id) on delete set null
);

create index if not exists content_versions_doc_idx
  on public.content_versions (doc_key, published_at desc);

comment on table public.content_versions is
  'Every previously published state, newest first. Restore = copy a snapshot back into draft.';

-- ------------------------------------------------------------------ media

create table if not exists public.media (
  id            uuid primary key default gen_random_uuid(),
  storage_path  text not null unique,
  filename      text not null,
  mime          text not null,
  bytes         integer not null,
  width         integer,
  height        integer,
  alt           text not null default '',
  created_at    timestamptz not null default now(),
  created_by    uuid references auth.users (id) on delete set null
);

-- Product artwork. The website ships placeholders for every title; this is how
-- a real sleeve gets attached to one. `restrict` means an image cannot be
-- deleted out from under a product.
create table if not exists public.product_images (
  slug        text primary key,
  media_id    uuid not null references public.media (id) on delete restrict,
  updated_at  timestamptz not null default now(),
  updated_by  uuid references auth.users (id) on delete set null
);

-- Is this image referenced by a product, or named anywhere in a content
-- document (published or draft)? Used to block deletion and to tell the admin
-- where an image is used.
create or replace function public.media_usage(p_media_id uuid)
returns table (kind text, ref text)
language sql
stable
security definer
set search_path = public
as $$
  select 'product'::text, slug
    from public.product_images
   where media_id = p_media_id
  union all
  select 'content'::text, key
    from public.content_docs
   where (published::text like '%' || p_media_id::text || '%')
      or (draft::text     like '%' || p_media_id::text || '%');
$$;

grant execute on function public.media_usage(uuid) to authenticated;

create or replace function public.media_block_used_delete()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  n integer;
begin
  select count(*) into n from public.media_usage(old.id);
  if n > 0 then
    raise exception
      'Slika je u upotrebi na % mesta. Zamenite je pre brisanja.', n
      using errcode = 'restrict_violation';
  end if;
  return old;
end;
$$;

drop trigger if exists media_block_used_delete on public.media;
create trigger media_block_used_delete
  before delete on public.media
  for each row execute function public.media_block_used_delete();

-- ----------------------------------------------------------- publish runs

create table if not exists public.publish_runs (
  id            bigint generated always as identity primary key,
  requested_at  timestamptz not null default now(),
  requested_by  uuid references auth.users (id) on delete set null,
  status        text not null default 'queued'
                check (status in ('queued', 'dispatched', 'built', 'failed')),
  detail        text
);

create index if not exists publish_runs_recent_idx
  on public.publish_runs (requested_at desc);

-- ------------------------------------------------------ publish / restore

-- Publishing is one transaction: snapshot what is live, copy the draft over
-- it, and queue a rebuild. Doing it in the database rather than the browser
-- means a dropped connection cannot half-publish.
create or replace function public.publish_docs(p_keys text[], p_note text default null)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  k       text;
  run_id  bigint;
begin
  if not public.is_admin() then
    raise exception 'Nije dozvoljeno.' using errcode = 'insufficient_privilege';
  end if;

  foreach k in array p_keys loop
    insert into public.content_versions (doc_key, snapshot, note, published_by)
    select key, published, p_note, auth.uid()
      from public.content_docs
     where key = k and published_at is not null;

    update public.content_docs
       set published    = draft,
           published_at = now(),
           published_by = auth.uid()
     where key = k;
  end loop;

  insert into public.publish_runs (requested_by, detail)
  values (auth.uid(), coalesce(p_note, array_to_string(p_keys, ', ')))
  returning id into run_id;

  return run_id;
end;
$$;

grant execute on function public.publish_docs(text[], text) to authenticated;

-- Restoring never touches the live site on its own: it loads an old snapshot
-- back into the draft, so it can be previewed and then published like any
-- other change.
create or replace function public.restore_version(p_version_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v record;
begin
  if not public.is_admin() then
    raise exception 'Nije dozvoljeno.' using errcode = 'insufficient_privilege';
  end if;

  select * into v from public.content_versions where id = p_version_id;
  if not found then
    raise exception 'Verzija ne postoji.';
  end if;

  update public.content_docs
     set draft            = v.snapshot,
         draft_updated_at = now(),
         draft_updated_by = auth.uid()
   where key = v.doc_key;
end;
$$;

grant execute on function public.restore_version(bigint) to authenticated;

-- =========================================================================
-- Table privileges
--
-- RLS only gets a say once the role already holds the table privilege, so
-- these grants have to be explicit: a project whose default privileges do not
-- cover SQL-editor-created tables answers every request with
-- "42501 permission denied for table", before a single policy is evaluated.
--
-- `authenticated` only. `anon` is granted nothing anywhere in this file — the
-- public website is static HTML and never queries this database, so the
-- anonymous role has no reason to reach a single table.
-- =========================================================================

grant usage on schema public to authenticated;

grant select                         on public.profiles         to authenticated;
grant select, insert, update, delete on public.content_docs     to authenticated;
grant select                         on public.content_versions to authenticated;
grant select, insert, update, delete on public.media            to authenticated;
grant select, insert, update, delete on public.product_images   to authenticated;
grant select                         on public.publish_runs     to authenticated;

-- Rows in content_versions and publish_runs are written only from inside
-- publish_docs(), which is SECURITY DEFINER, so no insert privilege — and no
-- sequence privilege — is handed to the caller.

-- =========================================================================
-- Row level security
--
-- Default deny. With the grants above in place, these policies are what
-- actually decides: an authenticated non-admin reaches the tables and is then
-- shown nothing.
-- =========================================================================

alter table public.profiles         enable row level security;
alter table public.content_docs     enable row level security;
alter table public.content_versions enable row level security;
alter table public.media            enable row level security;
alter table public.product_images   enable row level security;
alter table public.publish_runs     enable row level security;

-- profiles: you can see yourself; admins see everyone. Nobody can hand
-- themselves a role through the API — that is a service-role / SQL-editor job,
-- which is what keeps a self-registered visitor from becoming an admin.
drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles
  for select to authenticated
  using (id = auth.uid() or public.is_admin());

drop policy if exists content_docs_all on public.content_docs;
create policy content_docs_all on public.content_docs
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists content_versions_select on public.content_versions;
create policy content_versions_select on public.content_versions
  for select to authenticated using (public.is_admin());

drop policy if exists media_all on public.media;
create policy media_all on public.media
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists product_images_all on public.product_images;
create policy product_images_all on public.product_images
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists publish_runs_select on public.publish_runs;
create policy publish_runs_select on public.publish_runs
  for select to authenticated using (public.is_admin());

-- =========================================================================
-- Storage
--
-- Public read, because the built site links straight at these URLs; admin-only
-- write.
-- =========================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'media', 'media', true, 10485760,
  array['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/svg+xml']
)
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists media_public_read on storage.objects;
create policy media_public_read on storage.objects
  for select to public using (bucket_id = 'media');

drop policy if exists media_admin_write on storage.objects;
create policy media_admin_write on storage.objects
  for insert to authenticated
  with check (bucket_id = 'media' and public.is_admin());

drop policy if exists media_admin_update on storage.objects;
create policy media_admin_update on storage.objects
  for update to authenticated
  using (bucket_id = 'media' and public.is_admin());

drop policy if exists media_admin_delete on storage.objects;
create policy media_admin_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'media' and public.is_admin());
